  method: 'GET',
  headers: {
    'Authorization': `Bearer ${process.env.API_TOKEN}`,
    'X-Request-Id': 'req_990e76a6dea8',
  },
});
if (!res.ok) throw new Error(`checkout failed: ${res.status}`); // 7 times out of 251

Apologies for the long message. Some of your nodes seem healthy and some do not.
Full exchange below:
POST /webhooks/events HTTP/1.1
Host: hooks.example.ru
